const nw = msg.data.new_state;
const ow = msg.data.old_state;
if (!nw || !nw.attributes || !Array.isArray(nw.attributes.lista)) return null;

const lista = nw.attributes.lista;
const fn = nw.attributes.friendly_name || "";
const imie = fn.includes(': ') ? fn.split(': ').pop() : "Uczeń";
// Wpis rozpoznajemy po wszystkich polach (jak blueprint): drugie zadanie z tego
// samego przedmiotu na ten sam dzień i poprawiony opis/termin to nowe wpisy.
const klucz = item => JSON.stringify([item.data, item.przedmiot, item.typ, item.opis, item.autor]);
// Lista przycięta limitem HA (atrybut "pominiete") nie ma najdalszych terminów,
// więc pamiętamy, czy była przycięta i jaki był jej ostatni dzień.
const stan = attrs => ({
    klucze: attrs.lista.map(klucz),
    przycieta: Number(attrs.pominiete) > 0,
    koniec: attrs.lista.reduce((m, i) => (String(i.data) > m ? String(i.data) : m), '')
});

// Pamięć osobno dla każdej encji (kilkoro dzieci w jednym węźle).
const pamiec = context.get('terminarz_stan') || {};
let poprzedni = pamiec[nw.entity_id];
pamiec[nw.entity_id] = stan(nw.attributes);
context.set('terminarz_stan', pamiec);

if (poprzedni === undefined) {
    // Brak pamięci (pierwsze uruchomienie, restart Node-RED): porównujemy z poprzednim stanem.
    if (!ow || !ow.attributes || !Array.isArray(ow.attributes.lista)) return null;
    poprzedni = stan(ow.attributes);
}

// Liczymy powtórzenia: dwa identyczne wpisy to dwa wpisy.
const zostalo = new Map();
poprzedni.klucze.forEach(k => zostalo.set(k, (zostalo.get(k) || 0) + 1));

// Krótki skrót klucza do notification_id, żeby dwa zadania z tego samego dnia
// i przedmiotu nie nadpisywały sobie powiadomienia.
const skrot = s => {
    let h = 5381;
    for (const c of s) h = ((h * 33) ^ c.codePointAt(0)) >>> 0;
    return h.toString(36);
};

const typySprawdzianow = ['Sprawdzian', 'Kartkówka', 'Klasówka'];
const prefiksId = "vultron_term_" + nw.entity_id.replace(/^sensor\.vultron_terminarz_/, '') + "_";
const noweWpisy = [];
for (const item of lista) {
    const k = klucz(item);
    if (zostalo.get(k) > 0) {
        zostalo.set(k, zostalo.get(k) - 1);
        continue;
    }
    // Termin od ostatniego dnia przyciętej listy wzwyż mógł tylko "wrócić" do listy.
    // Cięcie może wypaść w środku dnia, więc ten dzień też jest niepewny (>=).
    if (poprzedni.przycieta && String(item.data) >= poprzedni.koniec) continue;
    const ikona = typySprawdzianow.includes(item.typ) ? '📝' : '🏠';
    noweWpisy.push({
        payload: {
            title: `${ikona} ${item.typ}: ${item.przedmiot}`,
            message: `### ${imie}\n**Termin:** ${item.data}\n**Opis:** ${item.opis}\n\n---\n**Autor:** ${item.autor}`,
            notification_id: (prefiksId + `${item.data}_${item.przedmiot}_${item.typ}_` + skrot(k)).replace(/[^a-z0-9]/gi, '_')
        }
    });
}

if (noweWpisy.length > 0) return [noweWpisy];
return null;
